package com.smarthub.plus;
import okhttp3.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
/** Direct HTTPS with normal certificate/hostname checks and a narrowly scoped DNS fallback. */
final class DirectHttp {
 static final class Reply {final int code;final byte[] bytes;final String location;Reply(int c,byte[] b,String l){code=c;bytes=b;location=l;}}
 private static final Map<String,List<InetAddress>> dns=new HashMap<>();private static final Map<String,Long> expires=new HashMap<>();
 private static boolean dnsHost(String h){return h.equals("i.imgur.com")||h.equals("api.themoviedb.org")||h.equals("image.tmdb.org")||h.equals("opensubtitles.com")||h.endsWith(".opensubtitles.com")||h.equals("osdb.link")||h.endsWith(".osdb.link");}
 private static List<InetAddress> lookup(String host)throws UnknownHostException{try{return Dns.SYSTEM.lookup(host);}catch(UnknownHostException original){if(!dnsHost(host))throw original;synchronized(dns){if(dns.containsKey(host)&&expires.get(host)>System.currentTimeMillis())return dns.get(host);}return externalLookup(host,original);}}
 private static List<InetAddress> externalLookup(String host,UnknownHostException original)throws UnknownHostException{for(String service:new String[]{"https://dns.google/resolve?name=","https://cloudflare-dns.com/dns-query?name="})try{HttpURLConnection c=(HttpURLConnection)new URL(service+URLEncoder.encode(host,"UTF-8")+"&type=A").openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Accept","application/dns-json");byte[] data;try{if(c.getResponseCode()!=200)continue;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[2048];int n;while((n=in.read(b))!=-1){if(out.size()+n>32768)throw new IOException("DNS response exceeds limit");out.write(b,0,n);}data=out.toByteArray();}}finally{c.disconnect();}JSONArray answers=new JSONObject(new String(data,java.nio.charset.StandardCharsets.UTF_8)).optJSONArray("Answer");List<InetAddress> found=new ArrayList<>();if(answers!=null)for(int n=0;n<answers.length();n++){JSONObject a=answers.optJSONObject(n);if(a==null||a.optInt("type")!=1)continue;String value=a.optString("data");if(!value.matches("[0-9]{1,3}(?:\\.[0-9]{1,3}){3}"))continue;String[] pieces=value.split("\\.");byte[] address=new byte[4];boolean valid=true;for(int i=0;i<4;i++){int v=Integer.parseInt(pieces[i]);if(v>255)valid=false;address[i]=(byte)v;}if(!valid)continue;InetAddress ip=InetAddress.getByAddress(host,address);if(ip.isAnyLocalAddress()||ip.isLoopbackAddress()||ip.isSiteLocalAddress()||ip.isLinkLocalAddress()||ip.isMulticastAddress())continue;found.add(ip);}if(!found.isEmpty()){synchronized(dns){dns.put(host,found);expires.put(host,System.currentTimeMillis()+300000);}return found;}}catch(Exception ignored){}throw original;}
 private static final OkHttpClient CLIENT=new OkHttpClient.Builder().dns(DirectHttp::lookup).connectTimeout(7,TimeUnit.SECONDS).readTimeout(20,TimeUnit.SECONDS).callTimeout(30,TimeUnit.SECONDS).followRedirects(false).followSslRedirects(false).retryOnConnectionFailure(false).build();
 static Reply request(String address,Map<String,String> headers,String body,int limit,Consumer<Call> active)throws Exception{URI uri=new URI(address);if(!"https".equals(uri.getScheme())||uri.getUserInfo()!=null||uri.getHost()==null)throw new IOException("HTTPS provider URL required");boolean secret=headers.keySet().stream().anyMatch(h->h.equalsIgnoreCase("Api-Key")||h.equalsIgnoreCase("X-API-Key")||h.equalsIgnoreCase("Authorization"));if(secret&&!Arrays.asList("api.opensubtitles.com","vip-api.opensubtitles.com","api.subsource.net","api.themoviedb.org").contains(uri.getHost()))throw new IOException("Credentials cannot be forwarded to an image or file host");Request.Builder builder=new Request.Builder().url(address).header("User-Agent","SmartHubPlus/1.5 (Android TV)");for(Map.Entry<String,String> h:headers.entrySet())builder.header(h.getKey(),h.getValue());if(body!=null)builder.post(RequestBody.create(MediaType.parse("application/json; charset=utf-8"),body.getBytes(java.nio.charset.StandardCharsets.UTF_8)));Call call=CLIENT.newCall(builder.build());if(active!=null)active.accept(call);try(Response response=call.execute()){try(InputStream in=response.body()==null?new ByteArrayInputStream(new byte[0]):response.body().byteStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted()){call.cancel();throw new InterruptedIOException("Cancelled");}if(out.size()+n>limit)throw new IOException("Provider response exceeds limit");out.write(b,0,n);}return new Reply(response.code(),out.toByteArray(),response.header("Location"));}}finally{if(active!=null)active.accept(null);}}
}
